from itertools import combinations
import random

def has_short_cycle(adj, n, max_len=7):
    # BFS from each vertex; detect cycle <= max_len
    for s in range(n):
        # BFS with parent
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            new_q = []
            for u in queue:
                if dist[u] >= max_len:
                    continue
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        new_q.append(v)
                    elif parent[u] != v:
                        # cycle found
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len <= max_len:
                            return True
            queue = new_q
    return False

# Actually, simpler: enumerate all cycles is hard. Let me check all pairs:
# For girth, for each edge (u,v), remove it and find shortest path u-v; shortest cycle through edge = 1 + shortest_path.
def girth(edges, n):
    from collections import defaultdict, deque
    adj = defaultdict(set)
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    g = float('inf')
    for u in range(n):
        # BFS
        dist = [-1]*n
        parent = [-1]*n
        dist[u] = 0
        q = deque([u])
        while q:
            x = q.popleft()
            for y in adj[x]:
                if dist[y] == -1:
                    dist[y] = dist[x]+1
                    parent[y] = x
                    q.append(y)
                elif parent[x] != y:
                    c = dist[x]+dist[y]+1
                    if c < g: g = c
    return g

