from collections import defaultdict, deque
import random

def girth_and_check(adj, n, limit=8):
    # Check if girth >= limit using BFS from each vertex
    for s in range(n):
        dist = [-1]*n
        dist[s] = 0
        parent = [-1]*n
        q = deque([s])
        while q:
            x = q.popleft()
            if dist[x] >= limit//2 + 1:
                continue
            for y in adj[x]:
                if dist[y] == -1:
                    dist[y] = dist[x]+1
                    parent[y] = x
                    q.append(y)
                elif parent[x] != y and dist[y] >= dist[x]:
                    c = dist[x]+dist[y]+1
                    if c < limit:
                        return False
    return True

