from collections import deque
from itertools import combinations

n = 16
def girth_of(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    g = float('inf')
    for s in range(n):
        dist = [-1]*n; dist[s]=0; parent=[-1]*n
        q = deque([s])
        while q:
            x = q.popleft()
            for y in adj[x]:
                if dist[y]==-1:
                    dist[y]=dist[x]+1; parent[y]=x; q.append(y)
                elif parent[x]!=y:
                    c = dist[x]+dist[y]+1
                    if c<g: g=c
    return g

